class Solution { public boolean canReorderDoubled(int[] arr){Map<Integer,Integer> count=new HashMap<>();Integer[] values=new Integer[arr.length];for(int i=0;i<arr.length;i++){values[i]=arr[i];count.merge(arr[i],1,Integer::sum);}Arrays.sort(values,Comparator.comparingInt(Math::abs));for(int x:values){if(count.get(x)==0)continue;if(count.getOrDefault(2*x,0)==0)return false;count.put(x,count.get(x)-1);count.put(2*x,count.get(2*x)-1);}return true;} }
